settings.custom_css:
.menu-scroll{border:1px solid #666; border-radius: 2px; padding: 10px;position:relative;background:#fff;}
.menu-scrl-list{margin:0px;text-align:center;}
.menu-scrl-list-item{display:inline-block;margin:0 10px;    font-family: "ivymode", Sans-serif; position:relative;
    font-size: 14px;
    font-weight: 400;
    text-transform: uppercase;
    line-height: 1em;
    letter-spacing: 1px;}
    .menu-scrl-list-item:before{
        content:"";
        display: list-item;
        position: absolute;
        left:5px;
        color:#f6851c;
        font-size: 20px;
        line-height: 14px;
    }
.menu-scrl-list-item div{display:inline-block;}

.warn-labels{text-align:center;line-height: 20px;}
.fdw-btn-all, .fdw-button,.warn-labels p{display:inline; font-size:12px;line-height: 12px; vertical-align:middle;letter-spacing:1px;text-transform:uppercase;text-align:center;border: 1px solid #ddd;}
.fdw-button, .fdw-btn-all{
  background-color: #eee;
  margin:5px 10px;height:32px;
  padding:0 10px;line-height:28px;
  border-radius: 25px;
  transition: all 200ms linear;
}

.warn-labels .fd-wrn{
  display: inline-block;
  color: #fff;
  width: 20px;
  height: 20px;
  font-size: 10px;
  line-height: 20px;
  vertical-align: middle;
  text-align: center;
  border-radius: 10px;
  font-weight: 600;
  margin-left: -5px;margin-top: -5px;}
.fdw-btn-all.active,.fdw-button.active{
    background-color: #fff;
    border-color: #AFCA05;
}
.warn-labels .fd-wrn.lbl-nuts{
    position: relative;
    display: inline-block;
}
.warn-labels .fd-wrn.lbl-nuts::before{
    content: '';
    width: 120%;
    position: absolute;
    right: -5%;
    top: 45%;
    border-bottom: 2px solid red;
    -webkit-transform: rotate(-45deg);
    transform: rotate(-45deg);
}

ul.food-list {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
}
li.food-item {
    list-style: none;
    display: inline-block;
    width: 30%;
    border-bottom: 1px solid #eee;
    margin: 0 1.66%;
    padding:1em 0;
}
.food-item h6{
  font-family: "ivymode", Sans-serif;
  font-size: 24px;display: inline;
  letter-spacing:1px;
}
.food-item p{margin: 0;
    text-transform: capitalize;
    letter-spacing: 0.5px;
    font-weight: 400;
    display: block;
    margin-top:0.5em;
    line-height: 20px;
    font-size: 16px;}
.fd-cat-desc{text-align:center;}
.food-cat{padding-top:0px;}
.food-cat-ttl{
  font-family: "ivymode", Sans-serif;
  padding-top:60px;padding-bottom:20px;
color:#344E41;
  font-size: 2em;
  text-align:center;
  margin-bottom:0.5em;
  letter-spacing:2px;border-bottom: 4px double #344E41;}
  .fd-wrn{display: none;
  color: #fff;
  width: 20px;
  height: 20px;
  margin-left: 5px;
  font-size: 10px;
  line-height: 20px;
  vertical-align: middle;
  text-align: center;
  border-radius: 10px;
  font-weight: 600;
  margin-top: -10px;}
  .vegan .fd-wrn.lbl-vegan,
  .gluten-free .fd-wrn.lbl-gluten,
  .jain .fd-wrn.lbl-jain,
  .nuts .fd-wrn.lbl-nuts{display:inline-block !important;}
   .fd-wrn.lbl-vegan{background:green}
   .fd-wrn.lbl-gluten{background:brown}
   .fd-wrn.lbl-jain{background:orange}
   .fd-wrn.lbl-nuts{background:black}
@media screen and (max-width: 1024px) {
  li.food-item {
    list-style: none;
    display: inline-block;
    width: 46.6%;
    border-bottom: 1px solid #eee;
    margin: 0 1.66%;
    padding:1em 0;
}
}
@media screen and (max-width: 768px) {
  li.food-item {
    list-style: none;
    display: inline-block;
    width: 96.6%;
    border-bottom: 1px solid #eee;
    margin: 0 1.66%;
    padding:1em 0;
}
}
